export type SemanticSnapshotProfile = (
  | {
      scope: {
        /**
         * Immutable reference to exactly one resolved semantic-world revision (world:<name>@sha256:<digest>); defined by DomainForge.
         */
        world_ref: string;
        /**
         * Mutable selector (world:<name>). Informational only; consequential records pin world_ref.
         */
        world_alias?: string;
        /**
         * Presentation only; never identity.
         */
        world_label?: string;
        [k: string]: unknown;
      };
      extensions?: {
        "domainforge.identity": {
          domain_model_identity: {
            identity_scheme_version: "v2-full-preimage";
            producer: string;
            producer_version: string;
            language_schema_version: string;
            compiler_interpretation_version: string;
            canonicalization_version: string;
            source_set_hash: string;
            content_hash: string;
            semantic_closure_hash: string;
            semantic_pack_set_hash: null | string;
            registry_content_hash: null | string;
            [k: string]: unknown;
          };
          semantic_closure_hash: string;
          [k: string]: unknown;
        };
        domainforge?: {
          model_validation_status?: "valid";
          [k: string]: unknown;
        };
        [k: string]: unknown;
      };
      [k: string]: unknown;
    }
  | {
      extensions: {
        domainforge: {
          model_validation_status: "invalid";
          [k: string]: unknown;
        };
        [k: string]: unknown;
      };
      [k: string]: unknown;
    }
) & {
  envelope_kind?: "semantic_snapshot";
  scope: {
    /**
     * Immutable reference to exactly one resolved semantic-world revision (world:<name>@sha256:<digest>); defined by DomainForge.
     */
    world_ref?: string;
    /**
     * Mutable selector (world:<name>). Informational only; consequential records pin world_ref.
     */
    world_alias?: string;
    /**
     * Presentation only; never identity.
     */
    world_label?: string;
    [k: string]: unknown;
  };
  extensions: {
    "cep.profile": {
      profile_id: "godspeed.semantic_snapshot";
      profile_version: "1.0.0";
      [k: string]: unknown;
    };
    [k: string]: unknown;
  };
  [k: string]: unknown;
};

