/**
 * Explicit move of work from one immutable semantic world to another. Never implied by an alias retarget. source_world_ref and target_world_ref must differ (checked by the typed validators).
 */
export interface WorldTransition {
  /**
   * World the work is pinned to today.
   */
  source_world_ref: string;
  /**
   * World the work moves to.
   */
  target_world_ref: string;
  transition_kind: "semantic_change" | "source_edit_only" | "compiler_upgrade" | "migration";
  reason: string;
  compatibility: "compatible" | "backward_compatible" | "breaking" | "unknown";
  /**
   * True only when both worlds have the same semantic_closure_hash.
   */
  semantic_closure_equal: boolean;
  semantic_diff_ref?: string;
  migration_ref?: string;
  authority_decision_ref?: string;
  evidence_refs?: string[];
}
